package com.dragonkey.monitor;
import android.inputmethodservice.InputMethodService;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import android.graphics.Color;import android.text.InputType;import java.io.*;
public class DragonKeyboard extends InputMethodService {
 LinearLayout layout; StringBuilder buffer=new StringBuilder();boolean sensitive=false;
 @Override public void onStartInput(EditorInfo info,boolean restarting){super.onStartInput(info,restarting);buffer.setLength(0);int cls=info.inputType & InputType.TYPE_MASK_CLASS;int variation=info.inputType & InputType.TYPE_MASK_VARIATION;sensitive=cls==InputType.TYPE_CLASS_NUMBER && (variation==InputType.TYPE_NUMBER_VARIATION_PASSWORD) || cls==InputType.TYPE_CLASS_TEXT && (variation==InputType.TYPE_TEXT_VARIATION_PASSWORD || variation==InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD || variation==InputType.TYPE_TEXT_VARIATION_WEB_PASSWORD || variation==InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS || variation==InputType.TYPE_TEXT_VARIATION_WEB_EMAIL_ADDRESS);sensitive |= (info.imeOptions & EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING)!=0;}
 @Override public View onCreateInputView(){layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(3,6,3,6);layout.setBackgroundColor(0xff040a17);String[] rows={"qwertyuiop","asdfghjkl","zxcvbnm"};for(String letters:rows){LinearLayout row=new LinearLayout(this);for(char c:letters.toCharArray()){add(row,String.valueOf(c),()->type(String.valueOf(c)),1);}layout.addView(row);}LinearLayout row=new LinearLayout(this);add(row,"⇧",()->{},1);add(row,"SPACE",()->type(" "),5);add(row,"⌫",()->{InputConnection ic=getCurrentInputConnection();if(ic!=null)ic.deleteSurroundingText(1,0);},2);add(row,"↵",()->{type("\n");flush();},2);layout.addView(row);TextView notice=new TextView(this);notice.setText("DRAGON KEY • registro voluntário • senhas excluídas");notice.setTextColor(0xff00baff);notice.setTextSize(11);notice.setPadding(10,6,0,6);layout.addView(notice);return layout;}
 void add(LinearLayout row,String label,Runnable action,int weight){Button b=new Button(this);b.setText(label);b.setTextSize(label.length()>2?11:17);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setPadding(0,0,0,0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff075b9b));row.addView(b,new LinearLayout.LayoutParams(0,56,weight));b.setOnClickListener(v->action.run());}
 void type(String s){InputConnection ic=getCurrentInputConnection();if(ic!=null)ic.commitText(s,1);if(!sensitive && getSharedPreferences("MainActivity",0).getBoolean("record",false)){buffer.append(s);if(s.equals("\n") || buffer.length()>=200)flush();}}
 void flush(){if(buffer.length()==0)return;if(!sensitive && getSharedPreferences("MainActivity",0).getBoolean("record",false)){try(FileOutputStream out=openFileOutput("history.txt",MODE_APPEND)){out.write((new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.getDefault()).format(new java.util.Date())+" | "+buffer.toString()+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}}buffer.setLength(0);}
 @Override public void onFinishInput(){flush();super.onFinishInput();}
}
